// ============================================================
// SYNTHETIC ASSET
// ============================================================
//
// Defines the market characteristics of an asset generated by the
// synthetic live market-data provider.
//
// Synthetic assets are used for development and engine testing only.
// They generate canonical market-data events such as `Quote` and
// `TapeTrade`, allowing strategies and the engine to operate exactly
// as they would with a real market-data provider.
//
// IMPORTANT:
// This module describes synthetic MARKET DATA only.
// It does not simulate order execution, fills, slippage, or venue
// behavior. Those responsibilities belong to the execution simulator.
//
// TODO:
// - Add configurable market regimes:
//      Normal
//      TrendingUp
//      TrendingDown
//      HighVolatility
//      Crash
//      Illiquid
//
// - Add configurable volatility regimes and regime transitions.
//
// - Add correlated assets so groups of symbols can move together.
//
// - Add market-wide shocks affecting multiple assets simultaneously.
//
// - Add configurable spread widening during volatile periods.
//
// - Add configurable liquidity / volume profiles.
//
// - Add intraday activity profiles such as:
//      market-open volatility
//      midday slowdown
//      market-close volatility
//
// - Add deterministic scenario definitions for reproducing specific
//   engine and strategy edge cases.
//
// - Add configurable quote/trade event rates independently.
//
// - Add price gaps and temporary liquidity disappearance.
//
// - Add large trade bursts for stress testing high-throughput paths.
//
// ============================================================

#[derive(Debug, Clone)]
pub struct SyntheticAsset {
    /// Symbol published through canonical market-data events.
    pub symbol: String,

    /// Initial midpoint/reference price when the synthetic feed starts.
    pub starting_price: f64,

    /// Approximate annualized volatility used by the price generator.
    ///
    /// Example:
    ///     0.20 = 20% annualized volatility.
    pub volatility: f64,

    /// Bid/ask spread expressed in basis points around the midpoint.
    ///
    /// Example:
    ///     2.0 = 2 basis points.
    pub spread_bps: f64,

    /// Number of synthetic market updates generated per second.
    pub events_per_second: u32,

    /// Minimum generated quote size.
    pub min_quote_size: f64,

    /// Maximum generated quote size.
    pub max_quote_size: f64,

    /// Minimum generated tape-trade size.
    pub min_trade_size: f64,

    /// Maximum generated tape-trade size.
    pub max_trade_size: f64,

    /// Deterministic random seed.
    ///
    /// Using the same asset configuration and seed should produce the
    /// same synthetic market sequence, making engine bugs reproducible.
    pub seed: u64,
}


// ============================================================
// CONSTRUCTOR
// ============================================================

impl SyntheticAsset {
    pub fn new(
        symbol: impl Into<String>,
        starting_price: f64,
        volatility: f64,
        spread_bps: f64,
        events_per_second: u32,
        seed: u64,
    ) -> Self {
        Self {
            symbol: symbol.into(),
            starting_price,
            volatility,
            spread_bps,
            events_per_second,
            min_quote_size: 1.0,
            max_quote_size: 500.0,
            min_trade_size: 1.0,
            max_trade_size: 100.0,
            seed,
        }
    }
}


// ============================================================
// DEFAULT TEST ASSETS
// ============================================================

/// Returns a standard group of deterministic synthetic assets.
///
/// These symbols intentionally do not correspond to real securities.
/// They can safely be used to distinguish synthetic market data from
/// live venue data in logs, strategies, and engine state.
pub fn default_synthetic_assets() -> Vec<SyntheticAsset> {
    vec![
        SyntheticAsset::new(
            "FAKEA",
            100.0,
            0.20,
            2.0,
            10,
            1,
        ),

        SyntheticAsset::new(
            "FAKEB",
            250.0,
            0.30,
            3.0,
            10,
            2,
        ),

        SyntheticAsset::new(
            "FAKEC",
            50.0,
            0.40,
            5.0,
            10,
            3,
        ),
    ]
}